// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the
// saving is here: returning no items stops every node below, and the
// execution ends having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql).
// A manual or webhook run always proceeds - a Run button that obeyed the
// cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A gate that fails CLOSED would silently disable the workflow the first time
// the settings row is missing or the RPC is absent - and a job that stopped
// running for a reason nobody can see is worse than one that runs too often.
// Fail OPEN, and say so.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  return [{ json: { __skipped: true, reason: decision.reason || 'not due' } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node is
// skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;
